<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Core.php';
use VanStal\Core;
$root=dirname(__DIR__); Core::boot($root); if(!Core::installed()){header('Location: install.php');exit;} $db=Core::db(); $route=$_GET['r']??'home';
function page(string $title, callable $body):void { $u=Core::user();?><!doctype html><html lang="nl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/app.css"><title><?=Core::e($title)?> · Van Stal Academie</title><body><header><a class="brand" href="index.php">Van Stal <small>Academie</small></a><nav><a href="index.php?r=courses">Cursussen</a><?php if($u):?><a href="index.php?r=dashboard">Dashboard</a><?php if(Core::can('courses.manage')):?><a href="index.php?r=manage">Beheer</a><?php endif?><span><?=Core::e($u['name'])?></span><a href="index.php?r=logout">Uitloggen</a><?php else:?><a href="index.php?r=login">Inloggen</a><a class="button small" href="index.php?r=register">Account maken</a><?php endif?></nav></header><main class="shell"><?php $body();?></main><footer>© <?=date('Y')?> Hondenschool Van Stal · Leeromgeving</footer></body></html><?php }
function flash():void{if($m=$_SESSION['flash']??null){unset($_SESSION['flash']);echo '<div class="alert">'.Core::e($m).'</div>';}}
function ownsCourse(int $id):void{if(!Core::courseManager($id))Core::fail(403,'Je mag deze cursus niet beheren.');}
if($route==='logout'){Core::logout();Core::redirect('home');}
if($route==='login' && $_SERVER['REQUEST_METHOD']==='POST'){Core::checkCsrf();$email=strtolower(trim($_POST['email']??''));$limit=(int)Core::config('security')['login_attempts'];$q=$db->prepare('SELECT COUNT(*) FROM login_attempts WHERE email=? AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$q->execute([$email]);if((int)$q->fetchColumn()>=$limit)Core::fail(429,'Te veel pogingen. Wacht 15 minuten.');$q=$db->prepare('SELECT u.*,r.name role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? AND u.status="active"');$q->execute([$email]);$user=$q->fetch();if(!$user||!password_verify($_POST['password']??'',$user['password_hash'])){$db->prepare('INSERT INTO login_attempts(email,ip_hash,attempted_at)VALUES(?,?,NOW())')->execute([$email,hash('sha256',$_SERVER['REMOTE_ADDR']??'')]);$_SESSION['flash']='E-mail of wachtwoord klopt niet.';Core::redirect('login');}Core::login($user);Core::audit('login','user',(int)$user['id']);Core::redirect('dashboard');}
if($route==='register'&&$_SERVER['REQUEST_METHOD']==='POST'){Core::checkCsrf();$email=filter_var(strtolower(trim($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$pass=$_POST['password']??'';$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');if(!$email||strlen($pass)<12||$first==='')Core::fail(422,'Vul naam, geldig e-mailadres en een wachtwoord van minimaal 12 tekens in.');try{$q=$db->prepare('INSERT INTO users(role_id,email,password_hash,first_name,last_name,created_at,updated_at)VALUES(3,?,?,?,?,NOW(),NOW())');$q->execute([$email,password_hash($pass,PASSWORD_ARGON2ID),$first,$last]);$_SESSION['flash']='Account aangemaakt. Je kunt nu inloggen.';Core::redirect('login');}catch(PDOException){Core::fail(422,'Dit e-mailadres is al geregistreerd.');}}
if($route==='enroll'&&$_SERVER['REQUEST_METHOD']==='POST'){Core::checkCsrf();$u=Core::requireLogin();$course=(int)$_POST['course_id'];$q=$db->prepare('SELECT enrollment_mode,status,max_participants FROM courses WHERE id=?');$q->execute([$course]);$c=$q->fetch();if(!$c||$c['status']!=='published')Core::fail(404,'Cursus niet beschikbaar.');$state=$c['enrollment_mode']==='open'?'approved':'requested';$q=$db->prepare('INSERT INTO enrollments(course_id,user_id,status,requested_at,decided_at) VALUES(?,?,?,NOW(),IF(?="approved",NOW(),NULL)) ON DUPLICATE KEY UPDATE status=IF(status="withdrawn",VALUES(status),status),requested_at=IF(status="withdrawn",NOW(),requested_at)');$q->execute([$course,$u['id'],$state,$state]);Core::audit('enroll_request','course',$course);$_SESSION['flash']=$state==='approved'?'Je bent ingeschreven.':'Je aanmelding wacht op goedkeuring.';Core::redirect('course',['id'=>$course]);}
if($route==='approve'&&$_SERVER['REQUEST_METHOD']==='POST'){Core::checkCsrf();Core::requireCan('enrollments.approve');$id=(int)$_POST['enrollment_id'];$q=$db->prepare('SELECT course_id FROM enrollments WHERE id=?');$q->execute([$id]);$course=(int)$q->fetchColumn();ownsCourse($course);$db->prepare("UPDATE enrollments SET status='approved',decided_at=NOW(),decided_by=? WHERE id=? AND status='requested'")->execute([Core::user()['id'],$id]);Core::audit('enrollment_approved','enrollment',$id);$_SESSION['flash']='Aanmelding goedgekeurd.';Core::redirect('manage',['course'=>$course]);}
if($route==='create_course'&&$_SERVER['REQUEST_METHOD']==='POST'){Core::checkCsrf();Core::requireCan('courses.manage');$title=trim($_POST['title']??'');$code=strtoupper(trim($_POST['code']??''));if(!$title||!preg_match('/^[A-Z0-9_-]{2,60}$/',$code))Core::fail(422,'Vul een naam en unieke code (letters, cijfers, - of _) in.');$q=$db->prepare('INSERT INTO courses(category_id,title,code,description,language,status,enrollment_mode,created_by,created_at,updated_at)VALUES(NULL,?,?,?,?,?,?,?,NOW(),NOW())');$q->execute([$title,$code,trim($_POST['description']??''),$_POST['language']==='en'?'en':'nl',$_POST['status']==='published'?'published':'draft',$_POST['mode']==='open'?'open':'approval',Core::user()['id']]);$id=(int)$db->lastInsertId();$db->prepare('INSERT INTO course_trainers(course_id,user_id)VALUES(?,?)')->execute([$id,Core::user()['id']]);Core::audit('course_created','course',$id);Core::redirect('manage',['course'=>$id]);}
if($route==='create_section'&&$_SERVER['REQUEST_METHOD']==='POST'){Core::checkCsrf();$course=(int)$_POST['course_id'];ownsCourse($course);$title=trim($_POST['title']??'');if($title==='')Core::fail(422,'Sectietitel ontbreekt.');$db->prepare('INSERT INTO sections(course_id,title,position)VALUES(?,?,(SELECT COALESCE(MAX(position),0)+1 FROM (SELECT position FROM sections WHERE course_id=?) s))')->execute([$course,$title,$course]);Core::redirect('manage',['course'=>$course]);}
if($route==='create_activity'&&$_SERVER['REQUEST_METHOD']==='POST'){Core::checkCsrf();$section=(int)$_POST['section_id'];$q=$db->prepare('SELECT course_id FROM sections WHERE id=?');$q->execute([$section]);$course=(int)$q->fetchColumn();ownsCourse($course);$title=trim($_POST['title']??'');if(!$title)Core::fail(422,'Lestitel ontbreekt.');$type=in_array($_POST['type']??'', ['page','link','file'],true)?$_POST['type']:'page';$db->prepare('INSERT INTO activities(section_id,type,title,content,url,position)VALUES(?,?,?,?,?,(SELECT COALESCE(MAX(position),0)+1 FROM (SELECT position FROM activities WHERE section_id=?) a))')->execute([$section,$type,$title,trim($_POST['content']??''),filter_var($_POST['url']??'',FILTER_SANITIZE_URL),$section]);Core::redirect('manage',['course'=>$course]);}
if($route==='complete'&&$_SERVER['REQUEST_METHOD']==='POST'){Core::checkCsrf();$u=Core::requireLogin();$activity=(int)$_POST['activity_id'];$q=$db->prepare('SELECT s.course_id FROM activities a JOIN sections s ON s.id=a.section_id WHERE a.id=?');$q->execute([$activity]);$course=(int)$q->fetchColumn();if(!Core::enrolled($course))Core::fail(403,'Geen toegang tot deze les.');$db->prepare('INSERT INTO activity_progress(activity_id,user_id,opened_at,completed_at)VALUES(?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE completed_at=NOW()')->execute([$activity,$u['id']]);Core::redirect('course',['id'=>$course]);}
if($route==='login'){page('Inloggen',function(){?><div class="auth"><h1>Welkom terug</h1><?php flash();?><form class="card stack" method="post"><input type="hidden" name="csrf" value="<?=Core::csrf()?>"><label>E-mailadres<input name="email" type="email" required autocomplete="email"></label><label>Wachtwoord<input name="password" type="password" required autocomplete="current-password"></label><button>Inloggen</button><a href="index.php?r=register">Nog geen account? Maak er één</a></form></div><?php });exit;}
if($route==='register'){page('Account maken',function(){?><div class="auth"><h1>Maak je account</h1><form class="card stack" method="post"><input type="hidden" name="csrf" value="<?=Core::csrf()?>"><label>Voornaam<input name="first_name" required></label><label>Achternaam<input name="last_name"></label><label>E-mailadres<input name="email" type="email" required></label><label>Wachtwoord <small>minimaal 12 tekens</small><input name="password" type="password" minlength="12" required></label><button>Account aanmaken</button></form></div><?php });exit;}
if($route==='courses'||$route==='home'){page($route==='home'?'Leren met je hond':'Cursussen',function()use($db,$route){$courses=$db->query("SELECT c.*,ca.name category,COUNT(e.id) count_enrolled FROM courses c LEFT JOIN categories ca ON ca.id=c.category_id LEFT JOIN enrollments e ON e.course_id=c.id AND e.status='approved' WHERE c.status='published' GROUP BY c.id ORDER BY c.created_at DESC")->fetchAll();?><section class="hero"><div><p class="eyebrow">Hondenschool Van Stal</p><h1><?= $route==='home'?'Samen leren, stap voor stap.':'Ontdek onze cursussen'?></h1><p>Praktische kennis, heldere lessen en begeleiding van onze trainers.</p><a class="button" href="index.php?r=courses">Bekijk cursussen</a></div></section><?php flash();?><div class="grid"><?php foreach($courses as $c):?><article class="card course"><span class="tag"><?=Core::e($c['language']==='en'?'English':'Nederlands')?></span><h2><?=Core::e($c['title'])?></h2><p><?=Core::e(mb_strimwidth((string)$c['description'],0,150,'…'))?></p><a href="index.php?r=course&id=<?=$c['id']?>">Bekijk cursus →</a></article><?php endforeach;if(!$courses):?><p>Nog geen gepubliceerde cursussen.</p><?php endif?></div><?php });exit;}
if($route==='course'){ $id=(int)($_GET['id']??0);$q=$db->prepare('SELECT c.*,ca.name category FROM courses c LEFT JOIN categories ca ON ca.id=c.category_id WHERE c.id=?');$q->execute([$id]);$course=$q->fetch();if(!$course||($course['status']!=='published'&&!Core::courseManager($id)))Core::fail(404,'Cursus niet gevonden.');$enrolled=Core::enrolled($id);$manager=Core::courseManager($id);$u=Core::user();$progress=$u?$db->prepare('SELECT a.id,a.title,a.type,a.content,a.url,ap.completed_at,s.title section_title FROM activities a JOIN sections s ON s.id=a.section_id LEFT JOIN activity_progress ap ON ap.activity_id=a.id AND ap.user_id=? WHERE s.course_id=? AND a.visible=1 ORDER BY s.position,a.position'):null;if($progress){$progress->execute([$u['id'],$id]);$activities=$progress->fetchAll();}else $activities=[];page($course['title'],function()use($course,$enrolled,$manager,$activities){?><div class="course-head"><p class="eyebrow"><?=Core::e($course['category']??'Cursus')?></p><h1><?=Core::e($course['title'])?></h1><p><?=nl2br(Core::e($course['description']))?></p><?php if(!$enrolled&&!$manager):if(Core::user()):?><form method="post" action="index.php?r=enroll"><input type="hidden" name="csrf" value="<?=Core::csrf()?>"><input type="hidden" name="course_id" value="<?=$course['id']?>"><button><?= $course['enrollment_mode']==='open'?'Direct inschrijven':'Aanmelden voor cursus'?></button></form><?php else:?><a class="button" href="index.php?r=login">Log in om je aan te melden</a><?php endif;endif?></div><?php if($enrolled||$manager):?><section><h2>Lesmateriaal</h2><?php $section='';foreach($activities as $a):if($section!==$a['section_title']):$section=$a['section_title'];?><h3 class="section-title"><?=Core::e($section)?></h3><?php endif?><article class="activity card"><div><span class="tag"><?=Core::e($a['type'])?></span><h3><?=Core::e($a['title'])?></h3><?php if($a['type']==='page'):?><p><?=nl2br(Core::e($a['content']))?></p><?php elseif($a['url']):?><a target="_blank" rel="noopener" href="<?=Core::e($a['url'])?>">Open materiaal</a><?php endif?></div><?php if($a['completed_at']):?><span class="done">Voltooid</span><?php else:?><form method="post" action="index.php?r=complete"><input type="hidden" name="csrf" value="<?=Core::csrf()?>"><input type="hidden" name="activity_id" value="<?=$a['id']?>"><button class="small">Markeer voltooid</button></form><?php endif?></article><?php endforeach;if(!$activities):?><p>Nog geen zichtbare lessen.</p><?php endif?></section><?php else:?><p class="notice">Meld je aan om het lesmateriaal te openen.</p><?php endif?><?php });exit;}
if($route==='dashboard'){ $u=Core::requireLogin();$q=$db->prepare("SELECT c.*,e.status,(SELECT COUNT(*) FROM activities a JOIN sections s ON s.id=a.section_id WHERE s.course_id=c.id AND a.completion_required=1) total,(SELECT COUNT(*) FROM activity_progress ap JOIN activities a ON a.id=ap.activity_id JOIN sections s ON s.id=a.section_id WHERE s.course_id=c.id AND ap.user_id=? AND ap.completed_at IS NOT NULL) done FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.requested_at DESC");$q->execute([$u['id'],$u['id']]);$rows=$q->fetchAll();page('Dashboard',function()use($rows,$u){?><h1>Goedemorgen, <?=Core::e($u['name'])?></h1><?php flash();?><h2>Mijn cursussen</h2><div class="grid"><?php foreach($rows as $c):$pct=$c['total']?(int)round(100*$c['done']/$c['total']):0?><article class="card"><span class="tag"><?=Core::e($c['status'])?></span><h2><?=Core::e($c['title'])?></h2><?php if($c['status']==='approved'):?><div class="progress"><i style="width:<?=$pct?>%"></i></div><p><?=$pct?>% voltooid</p><a href="index.php?r=course&id=<?=$c['id']?>">Verder leren →</a><?php else:?><p>Je aanmelding wacht op beoordeling.</p><?php endif?></article><?php endforeach;if(!$rows):?><p>Je bent nog niet aangemeld voor een cursus. <a href="index.php?r=courses">Bekijk het aanbod</a>.</p><?php endif?></div><?php });exit;}
if($route==='manage'){Core::requireCan('courses.manage');$course=(int)($_GET['course']??0);if(!$course){$u=Core::user();if($u['role']==='admin'){$courses=$db->query('SELECT * FROM courses ORDER BY created_at DESC')->fetchAll();}else{$q=$db->prepare('SELECT c.* FROM courses c JOIN course_trainers ct ON ct.course_id=c.id WHERE ct.user_id=? ORDER BY c.created_at DESC');$q->execute([$u['id']]);$courses=$q->fetchAll();}page('Cursusbeheer',function()use($courses){?><h1>Cursusbeheer</h1><div class="split"><section class="card"><h2>Nieuwe cursus</h2><form method="post" action="index.php?r=create_course" class="stack"><input type="hidden" name="csrf" value="<?=Core::csrf()?>"><label>Naam<input name="title" required></label><label>Code<input name="code" required></label><label>Beschrijving<textarea name="description"></textarea></label><label>Taal<select name="language"><option value="nl">Nederlands</option><option value="en">English</option></select></label><label>Status<select name="status"><option value="draft">Concept</option><option value="published">Gepubliceerd</option></select></label><label>Inschrijving<select name="mode"><option value="approval">Na goedkeuring</option><option value="open">Direct</option></select></label><button>Opslaan</button></form></section><section><h2>Mijn cursussen</h2><?php foreach($courses as $c):?><a class="card list" href="index.php?r=manage&course=<?=$c['id']?>"><strong><?=Core::e($c['title'])?></strong><span><?=Core::e($c['status'])?></span></a><?php endforeach?></section></div><?php });exit;}ownsCourse($course);$q=$db->prepare('SELECT * FROM courses WHERE id=?');$q->execute([$course]);$c=$q->fetch();$sections=$db->prepare('SELECT * FROM sections WHERE course_id=? ORDER BY position');$sections->execute([$course]);$sections=$sections->fetchAll();$en=$db->prepare("SELECT e.*,u.first_name,u.last_name,u.email FROM enrollments e JOIN users u ON u.id=e.user_id WHERE e.course_id=? AND e.status='requested'");$en->execute([$course]);$requests=$en->fetchAll();page('Beheer '.$c['title'],function()use($c,$sections,$requests,$db){?><p><a href="index.php?r=manage">← Alle cursussen</a></p><h1><?=Core::e($c['title'])?></h1><?php flash();?><div class="split"><section><h2>Lesstructuur</h2><form class="inline" method="post" action="index.php?r=create_section"><input type="hidden" name="csrf" value="<?=Core::csrf()?>"><input type="hidden" name="course_id" value="<?=$c['id']?>"><input name="title" placeholder="Nieuwe sectie" required><button>Toevoegen</button></form><?php foreach($sections as $s):$a=$db->prepare('SELECT * FROM activities WHERE section_id=? ORDER BY position');$a->execute([$s['id']]);?><article class="card"><h3><?=Core::e($s['title'])?></h3><?php foreach($a as $item):?><p>• <?=Core::e($item['title'])?> <small>(<?=Core::e($item['type'])?>)</small></p><?php endforeach?><form method="post" action="index.php?r=create_activity" class="stack compact"><input type="hidden" name="csrf" value="<?=Core::csrf()?>"><input type="hidden" name="section_id" value="<?=$s['id']?>"><input name="title" placeholder="Titel les" required><select name="type"><option value="page">Lespagina</option><option value="link">Externe link</option></select><textarea name="content" placeholder="Tekst van de les"></textarea><input name="url" type="url" placeholder="URL (voor link)"><button class="small">Les toevoegen</button></form></article><?php endforeach?></section><aside><h2>Aanmeldingen</h2><?php foreach($requests as $r):?><article class="card"><strong><?=Core::e($r['first_name'].' '.$r['last_name'])?></strong><small><?=Core::e($r['email'])?></small><form method="post" action="index.php?r=approve"><input type="hidden" name="csrf" value="<?=Core::csrf()?>"><input type="hidden" name="enrollment_id" value="<?=$r['id']?>"><button class="small">Goedkeuren</button></form></article><?php endforeach;if(!$requests):?><p>Geen openstaande aanmeldingen.</p><?php endif?></aside></div><?php });exit;}
Core::redirect('home');
